export function startSession(project,{minutes=25,goal=300,baseline=0},now=Date.now()){return {projectId:project.id,title:project.title,started:now,endsAt:now+Math.max(1,Math.min(120,minutes))*60000,goal:Math.max(0,Math.min(10000,goal)),baseline,finished:false};}
export function sessionProgress(session,wordCount,now=Date.now()){const remaining=Math.max(0,Math.ceil((session.endsAt-now)/1000)),written=Math.max(0,wordCount-session.baseline);return {remaining,written,complete:remaining===0,goalReached:session.goal>0&&written>=session.goal,clock:Math.floor(remaining/60)+':'+String(remaining%60).padStart(2,'0')};}
